import{_ as x,a0 as r,w as u,s as l,ao as p,I as e,x as o,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Mabox Linux：帶有 Openbox 的美麗的 Arch Linux | LCTT x X-CMD","titleTemplate":false,"description":"Mabox Linux：帶有 Openbox 的美麗的 Arch Linux | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Mabox Linux：帶有 Openbox 的美麗的 Arch Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Mabox Linux：帶有 Openbox 的美麗的 Arch Linux | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220321 Mabox Linux - Beautiful Arch Linux with Openbox -Review","title":"Mabox Linux：帶有 Openbox 的美麗的 Arch Linux","tag":"202203","desc":""},"relativePath":"202203/20220321 Mabox Linux - Beautiful Arch Linux with Openbox -Review.md","filePath":"[post].md"}'),b={name:"202203/20220321 Mabox Linux - Beautiful Arch Linux with Openbox -Review.md"};function s(d,n,m,h,L,M){const a=r("Link");return u(),l("div",null,[n[21]||(n[21]=p('<h1 id="mabox-linux-帶有-openbox-的美麗的-arch-linux" tabindex="-1">Mabox Linux：帶有 Openbox 的美麗的 Arch Linux <a class="header-anchor" href="#mabox-linux-帶有-openbox-的美麗的-arch-linux" aria-label="Permalink to “Mabox Linux：帶有 Openbox 的美麗的 Arch Linux”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202203/31/101104lieqiqhq3sezqtih.jpg" alt=""></p><blockquote><p>Mabox Linux 是一個 Manjaro Linux 重製版，帶有一個輕量級的 Openbox 窗口管理器，已經預配置了主題和實用程序。我們將在這篇文章中點評這個發行版。</p></blockquote><p>如果你喜歡窗口管理器，也喜歡基於滾動發佈的 Arch Linux，並且正在尋找一個具有這種組合的現成 Linux 發行版，可以試試 Mabox Linux。Mabox Linux 是建立在很棒的 Manjaro Linux 之上的，帶有 Openbox 窗口管理器和一些原生實用程序。</p><p>由於採用了 Openbox，這個 Linux 發行版在維持超輕量級的資源消耗的同時，也提供了一個漂亮的桌面。改編自 BunsenLabs，並受 Crunchbang 啓發的 Mabox Linux 工具也帶來了他們的一些應用。</p><p>讓我們來深入瞭解一下這個了不起的 Linux 發行版。</p><h3 id="mabox-linux-點評" tabindex="-1">Mabox Linux 點評 <a class="header-anchor" href="#mabox-linux-點評" aria-label="Permalink to “Mabox Linux 點評”">​</a></h3><h4 id="安裝和現場介質" tabindex="-1">安裝和現場介質 <a class="header-anchor" href="#安裝和現場介質" aria-label="Permalink to “安裝和現場介質”">​</a></h4><p>Mabox .ISO 的優勢之一是它在<ruby>現場介質<rt>Live medium</rt></ruby>啓動過程中為你提供了自由和專有的驅動程序的兩種選擇。如果你的系統中有英偉達或其他硬件，這對你有幫助。</p><p><ruby>現場桌面<rt>Live desktop</rt></ruby>讓你可以通過 Calamares 安裝程序來安裝 Mabox。在標準硬件上，安裝大約需要 3 到 4 分鐘，在我的測試中沒有遇到錯誤。</p><p>安裝程序也會檢測測試設備中的其他操作系統。</p><h4 id="具有自定義的外觀和感受" tabindex="-1">具有自定義的外觀和感受 <a class="header-anchor" href="#具有自定義的外觀和感受" aria-label="Permalink to “具有自定義的外觀和感受”">​</a></h4><p>Mabox 帶來了一個預配置的 Openbox 窗口管理器。這個搭配的版本看起來不錯，有深色外觀和帶面板的菜單。</p><p>頂部的面板是用 Tint2 構建的，分成兩個部分。左邊的面板為你提供了主菜單、文件管理器、網頁瀏覽器的快捷方式。面板上的鼠標左鍵和右鍵有不同的菜單。右邊的面板包含資源監視器、音量控制、截屏快捷方式和電源菜單。頂部面板不是連續的，在某些主題下，應用程序窗口會停留在頂部。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Mabox-Linux-with-Nord-Theme-1024x581.jpg" alt="Mabox Linux with Nord Theme"></p><p>在桌面的右邊部分，預配置的 Conky 腳本可以給你提供系統信息，包括日期、時間、存儲和其他顯示。</p><p>歡迎窗口為你提供了關於設置、幫助和支持的快速啓動快捷方式，並有文檔鏈接。</p><p>窗口管理器適合於鍵盤操作，有時不便於用鼠標操作。但由於 Openbox 和預配置的 Mabox，你可以輕鬆地使用鼠標，同時通過靈巧的鍵盤快捷方式提高你的工作效率。</p><p>桌面上的右鍵菜單為你提供了輕鬆的搜索和啓動選項。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Search-and-Launch-from-desktop.jpg" alt="Search and Launch from desktop"></p><p>如果你不喜歡默認的外觀，你可以通過 Openbox 和 Tint2 面板配置工具，只需點擊幾下就可以自行定製。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Main-Application-Menu.jpg" alt="Main Application Menu"></p><p>Mabox 預設有不同的主題，包括面板和 Concky 腳本。你可以點擊並應用這些令人驚歎的 Mabox 主題。如果你不想陷入自己配置面板、顏色和 Conky 的麻煩中，這是一個很好的功能。</p><p>一套好的牆紙可以讓你隨時讓它在短時間內看起來更加美妙。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Mabox-Themes.jpg" alt="Mabox Themes"></p><h4 id="應用" tabindex="-1">應用 <a class="header-anchor" href="#應用" aria-label="Permalink to “應用”">​</a></h4><p>Mabox Linux 將所有必要的應用打包在其安裝鏡像中。以下是所包含的基本應用的簡單列表。</p><ul><li>Terminator 終端</li><li>Xpad 快速寫字板</li><li>PCManFM 文件管理器</li><li>FSearch 桌面文件搜索</li><li>Flameshot 截圖工具</li><li>Geany 文本編輯器</li><li>Audacious 音樂播放器</li><li>Firefox 網頁瀏覽器</li></ul><p>Mabox 還包括控制中心，以有效管理你的系統。Mabox 控制中心可以讓你添加/刪除應用、更新你的系統、啓動窗口管理組件的幾個配置窗口，諸如此類。</p><p>如果你找不到某個設置，你可以在 Mabox 控制中心通過其系統設置的邏輯分組輕鬆找到它們。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Mabox-Control-Center.jpg" alt="Mabox Control Center"></p><h4 id="性能如何" tabindex="-1">性能如何？ <a class="header-anchor" href="#性能如何" aria-label="Permalink to “性能如何？”">​</a></h4><p>Mabox Linux 的性能令人印象非常深刻。由於採用了 Openbox 窗口管理器，Mabox 只用了大約 350MB 多點的內存，而 CPU 在空閒狀態下徘徊在 2% 到 3%。</p><p>默認安裝需要大約 5.39GB 的磁盤空間，這對於預裝的這些應用和設置程序來説是不可思議的。</p><p>在如此優化下，以至於它消耗內存最多的應用是 Xorg，有 90MB。</p><p>所以，我想嘗試一下重度使用下的性能。而這個性能也是令人驚訝的。我打開了一個文件管理器、帶三個標籤的 Firefox、一個用於開發的文本編輯器、一個終端窗口和控制中心。在這樣的工作負荷下，Mabox 只消耗了大約 920MB 的內存和 6% 到 7% 的 CPU。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Mabox-Linux-Heavy-Workload-Performance-1024x508.jpg" alt="Mabox Linux Heavy Workload Performance"></p>',37)),e("p",null,[n[1]||(n[1]=o("在 ",-1)),i(a,{href:"https://www.debugpoint.com/tag/linux-distro-review"},{default:t(()=>[...n[0]||(n[0]=[o("點評幾個發行版",-1)])]),_:1}),n[2]||(n[2]=o(" 的過程中，這是我第一次發現一個發行版在重度工作負荷下不超過 1GB 內存的情況。但在不同的使用情況下，結果可能有所不同。無論如何，這個指標還是令人印象深刻。",-1))]),n[22]||(n[22]=p('<h3 id="mabox-linux-可以作為日常使用嗎" tabindex="-1">Mabox Linux 可以作為日常使用嗎？ <a class="header-anchor" href="#mabox-linux-可以作為日常使用嗎" aria-label="Permalink to “Mabox Linux 可以作為日常使用嗎？”">​</a></h3><p>如果你對帶有窗口管理器的 Arch Linux 比較熟悉和適應，你可以把 Mabox Linux 作為日常使用。有幾個打包好的帶有窗口管理器的 Arch Linux 發行版，而 Mabox 是其中最好的一個。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Mabox-Linux-Windows-95-preconfigured-theme-1-1024x577.jpg" alt="Mabox Linux Windows 95 pre-configured theme"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我認為 Mabox Linux 團隊將所有組件與 Arch Linux 打包在一起，並呈現出一個漂亮的 Linux 發行版，做得非常好。它的外觀驚豔，而消耗的系統資源卻很少。有了基於 Arch Linux 的滾動發佈功能，我認為你可以信賴這個發行版的長期使用。</p>',5)),e("p",null,[n[4]||(n[4]=o("你可以從它的 ",-1)),i(a,{href:"https://maboxlinux.org/"},{default:t(()=>[...n[3]||(n[3]=[o("官方網頁",-1)])]),_:1}),n[5]||(n[5]=o(" 下載 Mabox Linux。",-1))]),n[23]||(n[23]=e("hr",null,null,-1)),e("p",null,[n[7]||(n[7]=o("via: ",-1)),i(a,{href:"https://www.debugpoint.com/2022/03/mabox-linux-2022/"},{default:t(()=>[...n[6]||(n[6]=[o("https://www.debugpoint.com/2022/03/mabox-linux-2022/",-1)])]),_:1})]),e("p",null,[n[12]||(n[12]=o("作者：",-1)),i(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...n[8]||(n[8]=[o("Arindam",-1)])]),_:1}),n[13]||(n[13]=o(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...n[9]||(n[9]=[o("lujun9972",-1)])]),_:1}),n[14]||(n[14]=o(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:t(()=>[...n[10]||(n[10]=[o("geekpi",-1)])]),_:1}),n[15]||(n[15]=o(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...n[11]||(n[11]=[o("wxy",-1)])]),_:1})]),e("p",null,[n[18]||(n[18]=o("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...n[16]||(n[16]=[o("LCTT",-1)])]),_:1}),n[19]||(n[19]=o(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...n[17]||(n[17]=[o("Linux中國",-1)])]),_:1}),n[20]||(n[20]=o(" 榮譽推出",-1))])])}const T=x(b,[["render",s]]);export{g as __pageData,T as default};
